    "tip.paletteBody": "\u30af\u30a4\u30c3\u30af\u30aa\u30fc\u30d7\u30f3\u306a\u3089\u30ef\u30fc\u30af\u30c4\u30ea\u30fc\u3082\u30d5\u30a1\u30a4\u30eb\u3082\u30ad\u30fc\u30dc\u30fc\u30c9\u3060\u3051\u3067\u63a2\u3057\u3066\u958b\u3051\u307e\u3059\u3002",
