    "tour.boardSearchBody": "\u540d\u524d\u304b\u30ef\u30fc\u30af\u30b9\u30da\u30fc\u30b9\u3067\u7d5e\u308a\u307e\u3059\u3002\u5f85\u6a5f\u4e2d\u306f\u65e2\u5b9a\u3067\u7573\u307e\u308c\u3066\u3044\u307e\u3059\u3002",
