    "emulator.realPhone.consent": "エージェントが実機「{{phone}}」を内部から操作する許可を求めています。許可すると、このMacでAppium WebDriverAgent {{tag}}に小さなパッチを加えた改変版をビルドし、チーム「{{team}}」（{{kind}}）の署名で実機に入れます。XcodeがあなたのApple アカウントにこのランナーのApp IDとプロビジョニングプロファイルを作ります。以後エージェントはMacのポインタなしで画面を読み、押し、入力できます。あなたが実機を使っている間も押せるので、止めるには実機をロックしてください。ロック解除とパスワード入力は行わず、支払い・振込はあなたのものです。この実機について、設定でオフにするかphone-removeを実行するまで続きます。許可するなら完了を押してください。",
    "emulator.realPhone.remove": "エージェントが「{{phone}}」のWebDriverAgentとこのMacのビルドを削除し、実機操作をオフにしようとしています。実機の他のものは変わりません。XcodeがApple アカウントに作ったApp IDとプロファイルは残ります。許可するなら完了を押してください。",
    "emulator.realPhone.androidConsent": "エージェントがAndroid実機「{{phone}}」をUSBまたはワイヤレスデバッグ（adb）で操作する許可を求めています。許可すると、どの言語でも入力できるよう小さな入力ヘルパーを実機の/data/local/tmpにコピーします。アプリはインストールしません。以後エージェントはMacのポインタなしで画面を読み、押し、スワイプし、入力できます。あなたが使っている間も押せるので、止めるには実機をロックしてください。ロック解除、電源キー、設定の変更、アプリの追加・削除、パスワード入力は行わず、支払い・振込はあなたのものです。この実機について、設定でオフにするかphone-removeを実行するまで続きます。許可するなら完了を押してください。",
    "emulator.realPhone.androidRemove": "エージェントがAndroid実機「{{phone}}」から入力ヘルパーを削除し、操作をオフにしようとしています。実機の他のものは変わりません。許可するなら完了を押してください。",
    "emulator.realPhone.title": "実機の操作",
    "emulator.realPhone.about": "エージェントが実機内の改変版WebDriverAgentでMacのポインタなしに操作します。オンにできるのは初回のカードであなただけで、実機ごとです。あなたが実機を使っている間もエージェントは押せるので、止めるには実機をロックしてください。ロック解除・パスワード・支払い・振込は常にあなたのものです。ビルド時にApple アカウントにこのランナーのApp IDとプロファイルが作られます。 Android実機はビルドなしにUSBデバッグで操作します。許可すると小さな入力ヘルパーを/data/local/tmpに置き、電源キー・設定・アプリには触れません。",
    "emulator.realPhone.allowed": "許可済み（オフにするとランナーを終了）",
    "emulator.realPhone.allowedOff": "オンにするのは、エージェントが初めて使うときに表示されるカードからです。",
